mapper.select:
SELECT P.PRODUCT_NO, P.STORE_NO, P.PRODUCT_NAME, P.BRAND, P.PRODUCT_PRICE, P.STOCK_QTY, P.A_SUB_NO, P.I_SUB_NO, P.PRODUCT_STATUS, DATE_FORMAT(P.CDATE, '%Y-%m-%d %H:%i:%s') AS CDATE, PA.A_MAIN_NO, PA.A_SUB_TYPE, PI.I_MAIN_NO, PI.I_SUB_TYPE, ( SELECT CONCAT(F.FILE_PATH, F.FILE_NAME) FROM PRODUCT_FILE F WHERE F.PRODUCT_NO = P.PRODUCT_NO AND F.IS_MAIN = 'Y' ORDER BY F.FILE_NO ASC LIMIT 1 ) AS MAIN_IMG FROM PRODUCT P INNER JOIN PC_ANIMAL_SUB PA ON P.A_SUB_NO = PA.A_SUB_NO INNER JOIN PC_ITEM_SUB PI ON P.I_SUB_NO = PI.I_SUB_NO WHERE 1=1 AND P.PRODUCT_STATUS = 'Y'
AND PA.A_MAIN_NO = #{aMainNo}
AND P.A_SUB_NO = #{aSubNo}
AND PI.I_MAIN_NO = #{iMainNo}
AND P.I_SUB_NO = #{iSubNo}
AND ( P.PRODUCT_NAME LIKE CONCAT('%', #{keyword}, '%') OR P.BRAND LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY P.PRODUCT_PRICE ASC, P.PRODUCT_NO DESC
ORDER BY P.PRODUCT_PRICE DESC, P.PRODUCT_NO DESC
ORDER BY P.PRODUCT_NO DESC
